// Owned process fixture only. Private local configuration arrives over stdin, never argv/logs.
import pg from'pg';import{startCreationService}from'../../src/server/creation-queues';import{CreationWake}from'../../src/domain/creation-queue';
if(process.env.LOCAL_DEVELOPMENT!=='true'||process.env.NODE_ENV!=='test')throw new Error('Owned test mode required.');let input='';for await(const part of process.stdin){input+=part.toString();if(input.length>8192)throw new Error('Configuration too large.');}const config=JSON.parse(input)as{connection:string;redis:string;prefix:string;receiver:string;mode:'normal'|'prestart'};
if(Object.keys(config).sort().join(',')!=='connection,mode,prefix,receiver,redis'||!['normal','prestart'].includes(config.mode)||!/^creation-fixture-[a-f0-9]{32}$/.test(config.prefix)||![config.connection,config.redis,config.receiver].every(value=>['localhost','127.0.0.1','postgres'].includes(new URL(value).hostname))||!/^creation_fixture_[a-f0-9]{32}$/.test(new URL(config.connection).pathname.slice(1)))throw new Error('Invalid isolated fixture configuration.');
const workerPool=new pg.Pool({connectionString:config.connection,options:'-c role=mailcraft_creation_worker -c statement_timeout=5000 -c lock_timeout=2000'}),schedulerPool=new pg.Pool({connectionString:config.connection,options:'-c role=mailcraft_creation_scheduler -c statement_timeout=5000 -c lock_timeout=2000'}),stop=new AbortController();
const service=await startCreationService({workerPool,schedulerPool,redisUrl:config.redis,prefix:config.prefix,signal:stop.signal,adapters:{preflight(){if(config.mode==='prestart'){process.stdout.write(JSON.stringify({event:'prepared',pid:process.pid})+'\n');Atomics.wait(new Int32Array(new SharedArrayBuffer(4)),0,0,10000);}},async generate(context,signal){const body=CreationWake.parse({workspace_id:context.operation.workspace_id,operation_id:context.operation.id});const response=await fetch(config.receiver,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal});if(!response.ok)throw new Error('Owned receiver failure.');return await response.json();},async extract(){throw new Error('Owned fixture has no extraction requests.');}}});process.stdout.write(JSON.stringify({event:'ready',pid:process.pid})+'\n');for(const signal of['SIGTERM','SIGINT']as const)process.on(signal,()=>stop.abort());await new Promise<void>(resolve=>stop.signal.addEventListener('abort',()=>resolve(),{once:true}));await service.close();await Promise.all([workerPool.end(),schedulerPool.end()]);
